373	    /**
374	     * Count the existing owners that share the given first name and last name, comparing each
375	     * case-insensitively (trimmed, with internal whitespace collapsed). The incoming owner is not
376	     * yet persisted, so it is not included in the count.
377	     *
378	     * @param firstName the incoming owner's first name
379	     * @param lastName  the incoming owner's last name
380	     * @return the number of existing namesakes
381	     */
382	    private int countNamesakes(String firstName, String lastName) {
383	        String normalizedFirstName = normalizeForComparison(firstName);
384	        String normalizedLastName = normalizeForComparison(lastName);
385	        return (int) this.clinicService.findAllOwners().stream()
386	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
387	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
388	            .count();
389	    }
